def _compute_packages_count(self):
    done_pickings = self.filtered(lambda picking: picking.state == 'done')
    other_pickings = self - done_pickings

    packages_by_pick = defaultdict(int)
    # Cannot _read_group() as picking_ids isn't stored, nor grouped() because multiple pickings per package
    packages = self.env['stock.package'].search([('picking_ids', 'in', other_pickings.ids)])
    for pack in packages:
        for picking in pack.picking_ids:
            packages_by_pick[picking] += 1

    histories_by_pick = self.env['stock.package.history']._read_group([
        ('picking_ids', 'in', done_pickings.ids)], ['picking_ids'], ['__count'])
    histories_by_pick = dict(histories_by_pick)

    for picking in done_pickings:
        picking.packages_count = histories_by_pick.get(picking, 0)
    for picking in other_pickings:
        picking.packages_count = packages_by_pick.get(picking, 0)

def _compute_show_check_availability(self):
    """ According to `picking.show_check_availability`, the "Reserve" button will be
    displayed in the form view of a picking.
    """
    for picking in self:
        if picking.state not in ('confirmed', 'waiting', 'assigned'):
            picking.show_check_availability = False
            continue
        if all(m.picked or m.product_uom_qty == m.quantity for m in picking.move_ids):
            picking.show_check_availability = False
            continue
        picking.show_check_availability = any(
            move.state in ('waiting', 'confirmed', 'partially_available') and
            move.uom_id.compare(move.product_uom_qty, 0)
            for move in picking.move_ids
        )

def _compute_validate_button_style(self):
    for picking in self:
        if picking.state in ('done', 'cancel'):
            picking.validate_button_style = 'invisible'
        elif picking.state in ('waiting', 'assigned'):
            picking.validate_button_style = 'primary'
        else:
            picking.validate_button_style = 'secondary'

def create(self, vals_list):
    scheduled_dates = []
    for vals in vals_list:
        defaults = self.default_get(['name', 'picking_type_id'])
        picking_type = self.env['stock.picking.type'].browse(vals.get('picking_type_id', defaults.get('picking_type_id')))
        if vals.get('name', '/') == '/' and defaults.get('name', '/') == '/' and vals.get('picking_type_id', defaults.get('picking_type_id')):
            if picking_type.sequence_id:
                vals['name'] = picking_type.sequence_id.next_by_id()

        # make sure to write `schedule_date` *after* the `stock.move` creation in
        # order to get a determinist execution of `_set_scheduled_date`
        scheduled_dates.append(vals.pop('scheduled_date', False))

    pickings = super().create(vals_list)

    for picking, scheduled_date in zip(pickings, scheduled_dates):
        if scheduled_date:
            picking.with_context(mail_notrack=True).write({'scheduled_date': scheduled_date})
    pickings._autoconfirm_picking()

    for picking, vals in zip(pickings, vals_list):
        if vals.get('batch_id'):
            if not picking.batch_id.picking_type_id:
                picking.batch_id.picking_type_id = picking.picking_type_id[0]
            picking.batch_id._sanity_check()

    return pickings

def action_cancel(self):
    self.move_ids._action_cancel()
    self.write({'is_locked': True})
    self.filtered(lambda x: not x.move_ids).state = 'cancel'
    # Remove the cancelled operation from its batch if the batch has other active picking(s).
    for picking in self:
        if picking.batch_id and any(picking.state != 'cancel' for picking in picking.batch_id.picking_ids):
            picking.batch_id = None
    return True

def _intercompany_unpack(self):
    if not self.env.user.has_group('stock.group_tracking_lot') or\
       not self.env['ir.config_parameter'].sudo().get_bool('stock.intercompany_auto_unpack'):
        return
    for picking in self:
        if not picking.partner_id:
            continue
        destination_company = self.env['res.company'].sudo().search([('partner_id', 'parent_of', picking.partner_id.id)], limit=1)
        if destination_company == picking.company_id:
            continue
        moves = picking.move_ids.filtered(lambda m: m.location_dest_id.usage == 'transit')
        moves.move_line_ids.result_package_id.unpack()

def _check_move_lines_map_quant_package(self, package):
    return package._check_move_lines_map_quant(self.move_line_ids.filtered(lambda ml:
        ml.product_id.is_storable
        and (ml.package_id == package or ml.package_id in package.all_children_package_ids)))

def _get_entire_pack_location_dest(self, move_line_ids):
    location_dest_ids = move_line_ids.mapped('location_dest_id')
    if len(location_dest_ids) > 1:
        return False
    return location_dest_ids.id

def _check_entire_pack(self):
    """ This function check if entire packs are moved in the picking"""
    for package, package_move_lines in self.move_line_ids.grouped('package_id').items():
        if not package:
            continue
        pickings = package_move_lines.picking_id
        if pickings._is_single_transfer() and pickings._check_move_lines_map_quant_package(package):
            move_lines_to_pack = package_move_lines.filtered(lambda ml: not ml.result_package_id and ml.state not in ('done', 'cancel'))
            if package.package_type_id.package_use != 'reusable':
                move_lines_to_pack.write({
                    'result_package_id': package.id,
                    'is_entire_pack': True,
                })
    # If we move all packages within a package, we can consider that they keep their container as well
    self.move_line_ids.result_package_id._apply_package_dest_for_entire_packs()

def _get_lot_move_lines_for_sanity_check(self, none_done_picking_ids, separate_pickings=True):
    """ Get all move_lines with tracked products that need to be checked over in the sanity check.
        :param none_done_picking_ids: Set of all pickings ids that have no quantity set on any move_line.
        :param separate_pickings: Indicates if pickings should be checked independently for lot/serial numbers or not.
    """
    def get_relevant_move_line_ids(none_done_picking_ids, picking):
        # Get all move_lines if picking has no quantity set, otherwise only get the move_lines with some quantity set.
        if picking.id in none_done_picking_ids:
            return picking.move_line_ids.filtered(lambda ml: ml.product_id and ml.product_id.tracking in ['lot', 'serial']).ids
        else:
            return get_line_with_done_qty_ids(picking.move_line_ids)

    def get_line_with_done_qty_ids(move_lines):
        # Get only move_lines that has some quantity set.
        return move_lines.filtered(lambda ml: ml.product_id.tracking in ['lot', 'serial'] and ml.picked and ml.uom_id.compare(ml.quantity, 0)).ids

    if separate_pickings:
        # If pickings are checked independently, get full/partial move_lines depending if each picking has no quantity set.
        lines_to_check_ids = [line_id for picking in self for line_id in get_relevant_move_line_ids(none_done_picking_ids, picking)]
    else:
        # If pickings are checked as one (like in a batch), then get only the move_lines with quantity across all pickings if there is at least one.
        if any(picking.id not in none_done_picking_ids for picking in self):
            lines_to_check_ids = get_line_with_done_qty_ids(self.move_line_ids)
        else:
            lines_to_check_ids = self.move_line_ids.filtered(lambda ml: ml.product_id and ml.product_id.tracking in ['lot', 'serial']).ids

    return self.env['stock.move.line'].browse(lines_to_check_ids)

def _sanity_check(self, separate_pickings=True):
    """ Sanity check for `button_validate()`
        :param separate_pickings: Indicates if pickings should be checked independently for lot/serial numbers or not.
    """
    pickings_without_lots = self.browse()
    products_without_lots = self.env['product.product']
    pickings_without_moves = self.filtered(lambda p: not p.move_ids and not p.move_line_ids)
    precision_digits = self.env['decimal.precision'].precision_get('Product Unit')

    no_quantities_done_ids = set()
    pickings_without_quantities = self.env['stock.picking']
    for picking in self:
        has_pick = any(move.picked and move.state not in ('done', 'cancel') for move in picking.move_ids)
        if all(float_is_zero(move.quantity, precision_digits=precision_digits) for move in picking.move_ids.filtered(lambda m: m.state not in ('done', 'cancel') and (not has_pick or m.picked))):
            pickings_without_quantities |= picking

    pickings_using_lots = self.filtered(lambda p: p.picking_type_id.use_create_lots or p.picking_type_id.use_existing_lots)
    if pickings_using_lots:
        lines_to_check = pickings_using_lots._get_lot_move_lines_for_sanity_check(no_quantities_done_ids, separate_pickings)
        for line in lines_to_check:
            if not line.lot_name and not line.lot_id:
                pickings_without_lots |= line.picking_id
                products_without_lots |= line.product_id

    if not self._should_show_transfers():
        if pickings_without_moves:
            raise UserError(_("You can’t validate an empty transfer. Please add some products to move before proceeding."))
        if pickings_without_quantities:
            raise UserError(self._get_without_quantities_error_message())
        if pickings_without_lots:
            raise UserError(_('You need to supply a Lot/Serial number for products %s.', ', '.join(products_without_lots.mapped('display_name'))))
    else:
        message = ""
        if pickings_without_moves:
            message += _('Transfers %s: Please add some items to move.', ', '.join(pickings_without_moves.mapped('name')))
        if pickings_without_lots:
            message += _(
                '\n\nTransfers %(transfer_list)s: You need to supply a Lot/Serial number for products %(product_list)s.',
                transfer_list=pickings_without_lots.mapped('name'),
                product_list=products_without_lots.mapped('display_name'),
            )
        if message:
            raise UserError(message.lstrip())

def button_validate(self):
    self = self.filtered(lambda p: p.state != 'done')
    draft_picking = self.filtered(lambda p: p.state == 'draft')
    res = draft_picking.with_context(to_validate=True).action_confirm()
    if res is not True:
        return res
    for move in draft_picking.move_ids:
        if move.uom_id.is_zero(move.quantity) and not move.uom_id.is_zero(move.product_uom_qty):
            move.quantity = move.product_uom_qty

    # Sanity checks.
    if not self.env.context.get('skip_sanity_check', False):
        self._sanity_check()

    # Run the pre-validation wizards. Processing a pre-validation wizard should work on the
    # moves and/or the context and never call `_action_done`.
    if not self.env.context.get('button_validate_picking_ids'):
        self = self.with_context(button_validate_picking_ids=self.ids)
    res = self._pre_action_done_hook()
    if res is not True:
        return res

    # Call `_action_done`.
    pickings_not_to_backorder = self.filtered(lambda p: p.picking_type_id.create_backorder == 'never')
    if self.env.context.get('picking_ids_not_to_backorder'):
        pickings_not_to_backorder |= self.browse(self.env.context['picking_ids_not_to_backorder']).filtered(
            lambda p: p.picking_type_id.create_backorder != 'always'
        )
    pickings_to_backorder = self - pickings_not_to_backorder
    if pickings_not_to_backorder:
        pickings_not_to_backorder.with_context(cancel_backorder=True)._action_done()
    if pickings_to_backorder:
        pickings_to_backorder.with_context(cancel_backorder=False)._action_done()

    # Remove done pickings from their batch.
    if any(picking.state == 'done' for picking in self):
        to_assign_ids = set()
        if self and self.env.context.get('pickings_to_detach'):
            pickings_to_detach = self.env['stock.picking'].browse(self.env.context['pickings_to_detach'])
            pickings_to_detach.batch_id = False
            pickings_to_detach.move_ids.filtered(lambda m: not m.quantity).picked = False
            to_assign_ids.update(self.env.context['pickings_to_detach'])

        for picking in self:
            if picking.state != 'done':
                continue
            # Avoid inconsistencies in states of the same batch when validating a single picking in a batch.
            if picking.batch_id and any(p.state != 'done' for p in picking.batch_id.picking_ids):
                picking.batch_id = None
            # If backorder were made and auto-batch is enabled, seek a batch for each of them with the selected criterias.
            to_assign_ids.update(picking.backorder_ids.ids)

        # If batch setting is enabled, auto-batch done pickings' backorders.
        if self.env.user.has_group('stock.group_stock_picking_batch'):
            # To avoid inconsistencies, all incorrect pickings must be removed before assigning backorder pickings
            assignable_pickings = self.env['stock.picking'].browse(to_assign_ids)
            for picking in assignable_pickings:
                picking._find_auto_batch()
            assignable_pickings.move_line_ids.with_context(skip_auto_waveable=True)._auto_wave()

    report_actions = self._get_autoprint_report_actions()
    if report_actions:
        return {
            'type': 'ir.actions.client',
            'tag': 'do_multi_print',
            'params': {
                'reports': report_actions,
            }
        }
    return True

def _pre_action_done_hook(self):
    for picking in self:
        has_quantity = False
        has_pick = False
        for move in picking.move_ids:
            if move.quantity:
                has_quantity = True
            if move.location_dest_usage == 'inventory':
                continue
            if move.picked:
                has_pick = True
            if has_quantity and has_pick:
                break
        if has_quantity and not has_pick:
            picking.move_ids.picked = True
    if not self.env.context.get('skip_backorder'):
        pickings_to_backorder = self._check_backorder()
        if pickings_to_backorder:
            return pickings_to_backorder._action_generate_backorder_wizard(show_transfers=self._should_show_transfers())
    return True

def _check_backorder(self):
    prec = self.env["decimal.precision"].precision_get("Product Unit")
    backorder_pickings = self.browse()
    for picking in self:
        if picking.picking_type_id.create_backorder != 'ask':
            continue
        if any(
                (move.product_uom_qty and not move.picked) or
                float_compare(move._get_picked_quantity(), move.product_uom_qty, precision_digits=prec) < 0
                for move in picking.move_ids
                if move.state != 'cancel'
        ):
            backorder_pickings |= picking
    return backorder_pickings

def _create_backorder_picking(self):
    self.ensure_one()
    return self.copy({
        'name': '/',
        'move_ids': [],
        'move_line_ids': [],
        'backorder_id': self.id,
        'return_id': self.return_id.id,
    })

def action_put_in_pack(self, *, package_id=False, package_type_id=False, package_name=False):
    self.ensure_one()
    if self.state not in ('done', 'cancel'):
        return self.move_line_ids.action_put_in_pack(package_id=package_id, package_type_id=package_type_id, package_name=package_name)

def action_see_packages(self):
    self.ensure_one()
    return {
        'name': self.env._("Packages"),
        'res_model': 'stock.package',
        'view_mode': 'list,kanban,form',
        'views': [(self.env.ref('stock.stock_package_view_list_editable').id, 'list'), (False, 'kanban'), (False, 'form')],
        'type': 'ir.actions.act_window',
        'domain': [('picking_ids', 'in', self.ids)],
        'context': {
            'picking_ids': self.ids,
            'location_id': self.location_id.id,
            'can_add_entire_packs': self.picking_type_code != 'incoming',
            'search_default_main_packages': True,
        },
    }

def action_see_package_histories(self):
    self.ensure_one()
    return {
        'name': self.env._("Packages"),
        'res_model': 'stock.package.history',
        'view_mode': 'list',
        'views': [(False, 'list')],
        'type': 'ir.actions.act_window',
        'domain': [('picking_ids', '=', self.id)],
        'context': {
            'search_default_main_packages': 1,
        },
    }

def _get_packages_for_print(self):
    package_ids = OrderedSet()
    for picking in self:
        if picking.state == 'done':
            package_ids.update(picking.package_history_ids.package_id.ids)
        else:
            package_ids.update(picking.move_line_ids.result_package_id._get_all_package_dest_ids())
    return self.env['stock.package'].browse(package_ids)

def _compute_picking_type_visible(self):
    repair_type_by_company = dict(self.env['stock.picking.type']._read_group([
            ('code', '=', 'repair_operation'),
            ('company_id', 'in', self.company_id.ids)
        ], groupby=['company_id'], aggregates=['__count']))
    for ro in self:
        ro.picking_type_visible = repair_type_by_company.get(ro.company_id, 0) > 1

def _compute_product_qty(self):
    for repair in self:
        if repair.picking_id:
            if repair.tracking in ['serial', 'lot'] and repair.lot_id:
                lot_move_lines = repair.picking_id.move_line_ids.filtered(lambda m: m.product_id == repair.product_id and m.lot_id == repair.lot_id)
                repair.product_qty = sum(lot_move_lines.mapped('quantity'))
            else:
                product_moves = repair.picking_id.move_ids.filtered(lambda m: m.product_id == repair.product_id)
                repair.product_qty = sum(product_moves.mapped('quantity'))
        else:
            repair.product_qty = 1.0

def _compute_allowed_uom_ids(self):
    for repair in self:
        repair.allowed_uom_ids = repair.product_id._get_available_uoms() | repair.product_id.seller_ids.uom_id

def _compute_partner_id(self):
    for repair in self:
        repair.partner_id = repair.picking_id.partner_id

def _compute_picking_product_ids(self):
    for repair in self:
        repair.picking_product_ids = repair.picking_id.move_ids.product_id

def _compute_allowed_lot_ids(self):
    for repair in self:
        domain = Domain('product_id', '=', repair.product_id.id)
        if repair.picking_id:
            domain &= Domain('id', 'in', repair.picking_id.move_ids.lot_ids.ids)
        repair.allowed_lot_ids = self.env['stock.lot'].search(domain)

def _compute_invoice_count(self):
    for repair in self:
        repair.invoice_count = len(repair.sudo().invoice_ids)

def _compute_can_create_sale_or_invoice(self):
    for repair in self:
        repair.can_create_sale_or_invoice = (
            repair.partner_id
            and not repair.sudo().invoice_ids
            and not repair.sale_order_id
            and repair.state != "cancel"
        )
        repair.can_create_extra_invoice = (
                repair.partner_id
                and all(invoice.state == "posted" for invoice in repair.invoice_ids)
                and not repair.sale_order_id
                and (
                    any(not move.invoice_line_ids for move in repair.move_ids)
                    or any(not repair_service_line.invoice_line_ids for repair_service_line in repair.repair_service_line_ids
                    )
                )
            )

def _compute_uom_id(self):
    for repair in self:
        if not repair.product_id:
            repair.uom_id = False
        elif not repair.uom_id:
            repair.uom_id = repair.product_id.uom_id

def _compute_lot_id(self):
    for repair in self:
        if (repair.product_id and repair.lot_id and repair.lot_id.product_id != repair.product_id) or not repair.product_id:
            repair.lot_id = False
        elif len(repair.picking_id.move_ids.lot_ids) == 1:
            repair.lot_id = repair.picking_id.move_ids.lot_ids

def _compute_picking_type_id(self):
    picking_type_by_company = self._get_picking_type()
    for ro in self:
        ro.picking_type_id = picking_type_by_company.get((ro.company_id, ro.user_id)) or\
            picking_type_by_company.get((ro.company_id, False))

def _compute_location_id(self):
    for repair in self:
        repair.location_id = repair.picking_type_id.default_location_src_id

def _compute_product_location_src_id(self):
    for record in self:
        record.product_location_src_id = record.picking_type_id.default_product_location_src_id

def _compute_product_location_dest_id(self):
    for record in self:
        record.product_location_dest_id = record.picking_type_id.default_product_location_dest_id

def _compute_recycle_location_id(self):
    for repair in self:
        repair.recycle_location_id = repair.picking_type_id.default_recycle_location_dest_id

def _compute_availability_boolean(self):
    self.is_parts_available, self.is_parts_late = False, False
    for repair in self:
        if not repair.parts_availability_state:
            continue
        if repair.parts_availability_state == 'available':
            repair.is_parts_available = True
        elif repair.parts_availability_state == 'late':
            repair.is_parts_late = True

def _compute_has_uncomplete_moves(self):
    for repair in self:
        repair.has_uncomplete_moves = any(move.uom_id and move.uom_id.compare(move.quantity, move.product_uom_qty) < 0 for move in repair.move_ids)

def _compute_unreserve_visible(self):
    for repair in self:
        repair.unreserve_visible = (
            repair.state == 'confirmed' and
            any(repair.move_ids.move_line_ids.mapped('quantity_product_uom'))
        )
        repair.reserve_visible = (
            repair.state == 'confirmed' and
            any(not move.picked and move.product_uom_qty and move.state in ['confirmed', 'partially_available'] for move in repair.move_ids)
        )

def _compute_validate_button_style(self):
    for repair in self:
        if repair.state in ('cancel', 'done', 'draft'):
            repair.validate_button_style = 'invisible'
        elif repair.state == 'confirmed':
            repair.validate_button_style = 'primary'
        else:
            repair.validate_button_style = 'secondary'

def _search_date_category(self, operator, value):
    if operator != 'in':
        return NotImplemented
    return Domain.OR(
        self.env['stock.picking'].date_category_to_domain('schedule_date', item)
        for item in value
    )

def onchange_uom_id(self):
    res = {}
    if not self.product_id or not self.uom_id:
        return res
    return res

def _onchange_location_picking(self):
    location_warehouse = self.location_id.warehouse_id
    picking_warehouse = self.picking_id.location_dest_id.warehouse_id
    if location_warehouse and picking_warehouse and location_warehouse != picking_warehouse:
        return {
            'warning': {'title': _("Warning"), 'message': _("Note that the warehouses of the return and repair locations don't match!")},
        }

def create(self, vals_list):
    # We generate a standard reference
    for vals in vals_list:
        picking_type = self.env['stock.picking.type'].browse(
            vals.get('picking_type_id', self.default_get(['picking_type_id'])['picking_type_id'])
        )
        if 'picking_type_id' not in vals:
            vals['picking_type_id'] = picking_type.id
        if not vals.get('name', False) or vals['name'] == _('New'):
            vals['name'] = picking_type.sequence_id.next_by_id()
        if not vals.get('reference_ids'):
            vals['reference_ids'] = [Command.link(self.env["stock.reference"].create({'name': vals['name']}).id)]
    return super().create(vals_list)

def write(self, vals):
    moves_to_reassign = self.env['stock.move']
    if vals.get('picking_type_id'):
        picking_type = self.env['stock.picking.type'].browse(vals.get('picking_type_id'))
        for repair in self:
            if repair.state in ('cancel', 'done'):
                continue
            if picking_type != repair.picking_type_id:
                repair.name = picking_type.sequence_id.next_by_id()
                moves_to_reassign |= repair.move_ids
    res = super().write(vals)
    if 'product_id' in vals and self.tracking == 'serial':
        self.write({'product_qty': 1.0})

    for repair in self:
        has_modified_location = any(key in vals for key in MAP_REPAIR_TO_PICKING_LOCATIONS)
        if has_modified_location:
            repair.move_ids._set_repair_locations()
        if 'schedule_date' in vals:
            (repair.move_id + repair.move_ids).filtered(lambda m: m.state not in ('done', 'cancel')).write({'date': repair.schedule_date})
        if 'under_warranty' in vals:
            repair._update_sale_order_line_price()
            repair._update_invoice_line_price()
    if moves_to_reassign:
        moves_to_reassign._do_unreserve()
        moves_to_reassign = moves_to_reassign._filtered_for_assign()
        moves_to_reassign._action_assign()
    return res

