protected void checkOngoingInventory(StockMove stockMove) throws AxelorException {

  BatchProcessorHelper batchHelper =
      BatchProcessorHelper.builder().flushAfterBatch(false).build();

  Set<Long> stockLocationIds = new HashSet<>();
  Set<Long> productIds = new HashSet<>();
  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> smlQuery = getStockMoveLineQuery(stockMoveId);

  batchHelper.<StockMoveLine>forEachByQuery(
      smlQuery,
      sml -> {
        StockLocation from = sml.getFromStockLocation();
        StockLocation to = sml.getToStockLocation();
        if (from != null && from.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
          stockLocationIds.add(from.getId());
          Set<Long> locationIds =
              stockLocationService
                  .getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(from);
          if (locationIds != null) {
            stockLocationIds.addAll(locationIds);
          }
        }
        if (to != null && to.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
          stockLocationIds.add(to.getId());
          Set<Long> locationIds =
              stockLocationService
                  .getLocationAndAllParentLocationsIdsOrderedFromTheClosestToTheFurthest(to);
          if (locationIds != null) {
            stockLocationIds.addAll(locationIds);
          }
        }

        if (sml.getProduct() != null) {
          productIds.add(sml.getProduct().getId());
        }
      });

  if (stockLocationIds.isEmpty() || productIds.isEmpty()) {
    return;
  }

  InventoryLineRepository inventoryLineRepo = Beans.get(InventoryLineRepository.class);

  InventoryLine inventoryLine =
      inventoryLineRepo
          .all()
          .filter(
              "self.inventory.isStockMoveBlocked = true\n"
                  + "AND self.inventory.stockLocation.id IN (:stockLocationIds)\n"
                  + "AND self.product.id IN (:productList)")
          .bind("stockLocationIds", stockLocationIds)
          .bind("productList", productIds)
          .fetchOne();

  if (inventoryLine != null) {
    throw new AxelorException(
        inventoryLine,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_19),
        inventoryLine.getInventory().getInventorySeq());
  }
}

protected void processBackorderLine(StockMoveLine stockMoveLine, StockMove newStockMove)
    throws AxelorException {
  if (stockMoveLine.getQty().compareTo(stockMoveLine.getRealQty()) <= 0) {
    return;
  }
  StockMoveLine newStockMoveLine = copySplittedStockMoveLine(stockMoveLine);
  newStockMove.addStockMoveLineListItem(newStockMoveLine);

  Product product = newStockMoveLine.getProduct();
  if (product != null) {
    TrackingNumberConfiguration trackingNumberConfiguration =
        (TrackingNumberConfiguration)
            productCompanyService.get(
                product, "trackingNumberConfiguration", newStockMove.getCompany());

    newStockMoveLine.setTrackingNumber(null);
    stockMoveLineService.assignOrGenerateTrackingNumber(
        newStockMoveLine,
        newStockMove,
        product,
        trackingNumberConfiguration,
        newStockMove.getTypeSelect() == StockMoveRepository.TYPE_OUTGOING
            ? StockMoveLineService.TYPE_SALES
            : StockMoveLineService.TYPE_PURCHASES);
  }
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void cancel(StockMove stockMove, CancelReason cancelReason) throws AxelorException {
  List<Integer> authorizedStatus = new ArrayList<>();
  authorizedStatus.add(StockMoveRepository.STATUS_PLANNED);
  authorizedStatus.add(StockMoveRepository.STATUS_REALIZED);
  if (stockMove.getStatusSelect() == null
      || !authorizedStatus.contains(stockMove.getStatusSelect())) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_CANCEL_WRONG_STATUS));
  }
  applyCancelReason(stockMove, cancelReason);
  cancel(stockMove);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void cancel(StockMove stockMove) throws AxelorException {
  LOG.debug("Stock move cancel : {} ", stockMove.getStockMoveSeq());
  checkReversionStatus(stockMove);
  int initialStatus = stockMove.getStatusSelect();
  setCancelStatus(stockMove);

  if (initialStatus == StockMoveRepository.STATUS_PLANNED) {
    stockMoveLineService.updateLocations(
        initialStatus,
        StockMoveRepository.STATUS_CANCELED,
        getPlannedStockMoveLineIds(stockMove, false),
        stockMove.getEstimatedDate(),
        false,
        false);
  } else {
    stockMoveLineService.updateLocations(
        initialStatus,
        StockMoveRepository.STATUS_CANCELED,
        stockMove.getStockMoveLineList().stream()
            .map(StockMoveLine::getId)
            .collect(Collectors.toSet()),
        stockMove.getEstimatedDate(),
        true,
        true);
    stockMove.setRealDate(appBaseService.getTodayDate(stockMove.getCompany()));
    Set<Long> productIds =
        stockMove.getStockMoveLineList().stream()
            .map(StockMoveLine::getProduct)
            .filter(p -> p != null)
            .map(Product::getId)
            .collect(Collectors.toSet());
    weightedAveragePriceService.resetAvgPriceForProducts(productIds);
  }

  clearPlannedStockMoveLine(stockMove, false);
  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && initialStatus == StockMoveRepository.STATUS_REALIZED) {
    partnerProductQualityRatingService.undoCalculation(stockMove);
  }
}

@Override
public void checkReversionStatus(StockMove stockMove) throws AxelorException {
  if (stockMove == null || stockMove.getId() == null) {
    return;
  }
  List<StockMove> reversionStockMoveList =
      stockMoveRepo
          .all()
          .filter(
              "self.reversionOriginStockMove.id = :stockMoveId"
                  + " AND self.statusSelect IN (:planned, :realized)")
          .bind("stockMoveId", stockMove.getId())
          .bind("planned", StockMoveRepository.STATUS_PLANNED)
          .bind("realized", StockMoveRepository.STATUS_REALIZED)
          .order("stockMoveSeq")
          .fetch();
  if (reversionStockMoveList.isEmpty()) {
    return;
  }
  throw new AxelorException(
      stockMove,
      TraceBackRepository.CATEGORY_INCONSISTENCY,
      String.format(
          I18n.get(StockExceptionMessage.STOCK_MOVE_CANCEL_WRONG_REVERSION_STATUS),
          stockMove.getStockMoveSeq(),
          reversionStockMoveList.stream()
              .map(StockMove::getStockMoveSeq)
              .collect(Collectors.joining(", "))));
}

protected void setCancelStatus(StockMove stockMove) {
