def validate_picked_materials(item_code, required_qty, locations, picked_item_details=None):
	for location in list(locations):
		if location["qty"] < 0:
			locations.remove(location)

	total_qty_available = sum(location.get("qty") for location in locations)
	remaining_qty = required_qty - total_qty_available

	if remaining_qty > 0:
		if picked_item_details:
			frappe.msgprint(
				_(
					"{0} units of Item {1} is not available in any of the warehouses. Other Pick Lists exist for this item."
				).format(remaining_qty, get_link_to_form("Item", item_code)),
				title=_("Already Picked"),
			)
		else:
			frappe.msgprint(
				_("{0} units of Item {1} is not available in any of the warehouses.").format(
					remaining_qty, get_link_to_form("Item", item_code)
				),
				title=_("Insufficient Stock"),
			)

def create_delivery(
	source_name: str, target_doc: str | dict | Document | None = None, target: str | None = None
):
	pick_list = frappe.get_doc("Pick List", source_name)
	pick_list.check_permission("read")
	target = target or (frappe.flags.args or {}).get("target") or "Delivery Note"
	validate_item_locations(pick_list)
	sales_dict = dict()
	documents = []
	sales_orders = get_sales_order_headers({location.sales_order for location in pick_list.locations})

	for key, rows in groupby(sorted(sales_orders, key=get_header_key), key=get_header_key):
		sales_dict[key] = {row.sales_order for row in rows}

	if sales_dict:
		documents.extend(create_delivery_with_so(sales_dict, pick_list, target))

	if not all(item.sales_order for item in pick_list.locations):
		documents.append(create_delivery_wo_so(pick_list, target, target_doc))

	if len(documents) == 1:
		return documents[0]
	else:
		from frappe.utils import comma_and

		doc_list = [get_link_to_form(target, p.name) for p in documents]
		frappe.msgprint(_("{0} created").format(comma_and(doc_list)))

def create_delivery_wo_so(pick_list, target, target_doc=None, selected_locations=None):
	if not target_doc:
		target_doc = frappe.new_doc(target)

	target_doc.company = pick_list.company

	if not target_doc.customer:
		target_doc.customer = pick_list.customer

	item_table_mapper_without_so = {
		"doctype": f"{target} Item",
		"field_map": {
			"rate": "rate",
			"name": "name",
			"parent": "",
		},
	}
	map_pl_locations(
		pick_list, item_table_mapper_without_so, target_doc, selected_locations=selected_locations
	)
	target_doc.flags.ignore_mandatory = True
	if target == "Sales Invoice":
		target_doc.update_stock = 1
	target_doc.save()

	return target_doc

def create_dn_for_pick_lists(
	source_name: str, target_doc: str | dict | Document | None = None, kwargs: str | dict | None = None
):
	"""Get Items from Multiple Pick Lists and create a Delivery Note for filtered customer"""
	if kwargs is None:
		kwargs = {}
	if isinstance(kwargs, str):
		kwargs = json.loads(kwargs)

	pick_list = frappe.get_doc("Pick List", source_name)
	pick_list.check_permission("read")
	validate_item_locations(pick_list)

	sales_order_arg = kwargs.get("sales_order")
	customer_arg = kwargs.get("customer")

	if sales_order_arg:
		sales_orders = {sales_order_arg}
	else:
		sales_orders = {row.sales_order for row in pick_list.locations if row.sales_order}

		if customer_arg:
			sales_orders = frappe.get_all(
				"Sales Order",
				filters={"customer": customer_arg, "name": ["in", list(sales_orders)]},
				pluck="name",
			)

	delivery_note = create_delivery_from_so(
		pick_list, sales_orders, "Delivery Note", target_doc=target_doc, kwargs=kwargs
	)

	if not sales_order_arg and not all(item.sales_order for item in pick_list.locations):
		if isinstance(delivery_note, str):
			delivery_note = frappe.get_doc(frappe.parse_json(delivery_note))

		delivery_note = create_delivery_wo_so(
			pick_list, "Delivery Note", delivery_note, set(kwargs.get("filtered_children") or [])
		)

	return delivery_note

def create_dn_from_so(pick_list, sales_order_list, delivery_note=None, kwargs=None):
	return create_delivery_from_so(
		pick_list, sales_order_list, "Delivery Note", target_doc=delivery_note, kwargs=kwargs
	)

def create_delivery_from_so(pick_list, sales_order_list, target, target_doc=None, kwargs=None):
	if not sales_order_list:
		return target_doc

	if kwargs is None:
		kwargs = {}

	item_table_mapper = {
		"doctype": f"{target} Item",
		"field_map": {
			"rate": "rate",
			"name": "so_detail",
			"parent": "against_sales_order" if target == "Delivery Note" else "sales_order",
		},
		"condition": lambda doc: abs(doc.delivered_qty) < abs(doc.qty) and doc.delivered_by_supplier != 1,
	}
	selected_locations = set(kwargs.get("filtered_children") or [])

	mapper_kwargs = {"skip_item_mapping": True, "ignore_pricing_rule": pick_list.ignore_pricing_rule}

	target_doc = (
		create_delivery_note_from_sales_order(next(iter(sales_order_list)), target_doc, kwargs=mapper_kwargs)
		if target == "Delivery Note"
		else create_sales_invoice_from_sales_order(
			next(iter(sales_order_list)), target_doc, args=mapper_kwargs
		)
	)

	if not target_doc:
		return

	for so in sales_order_list:
		map_pl_locations(pick_list, item_table_mapper, target_doc, so, selected_locations)

	return target_doc

def create_stock_entry(pick_list: str | dict):
	pick_list = frappe.get_doc(frappe.parse_json(pick_list))
	pick_list.check_permission("read")
	validate_item_locations(pick_list)

	stock_entry = frappe.new_doc("Stock Entry")
	stock_entry.pick_list = pick_list.get("name")
	stock_entry.purpose = pick_list.get("purpose")
	stock_entry.company = pick_list.get("company")

	job_card = pick_list.get("material_request") and frappe.db.get_value(
		"Material Request", pick_list.get("material_request"), "job_card"
	)

	if job_card:
		stock_entry = update_stock_entry_based_on_job_card(pick_list, stock_entry, job_card)
	elif pick_list.get("work_order"):
		stock_entry = update_stock_entry_based_on_work_order(pick_list, stock_entry)
	elif pick_list.get("material_request"):
		stock_entry = update_stock_entry_based_on_material_request(pick_list, stock_entry)
	else:
		stock_entry = update_stock_entry_items_with_no_reference(pick_list, stock_entry)

	stock_entry.set_stock_entry_type()

	if not stock_entry.get("items"):
		return frappe.msgprint(_("All picked items have already been transferred against this Pick List"))

	stock_entry.set_missing_values()

	return stock_entry.as_dict()

def before_cancel(self):
	if self.flags.cancelled_by_delivery_note:
		return

	if cint(frappe.db.get_value("Delivery Note", self.delivery_note, "docstatus")) == 1:
		frappe.throw(
			_("Packing Slip cannot be cancelled as Delivery Note {0} is already submitted.").format(
				frappe.bold(self.delivery_note)
			)
		)

def validate_delivery_note(self):
	"""Raises an exception if the `Delivery Note` status is not Draft"""

	if cint(frappe.db.get_value("Delivery Note", self.delivery_note, "docstatus")) != 0:
		frappe.throw(
			_("A Packing Slip can only be created for Draft Delivery Note.").format(self.delivery_note)
		)

def validate_case_nos(self):
	"""Validate if case nos overlap. If they do, recommend next case no."""

	if cint(self.from_case_no) <= 0:
		frappe.throw(_("The 'From Package No.' field must neither be empty nor it's value less than 1."))
	elif not self.to_case_no:
		self.to_case_no = self.from_case_no
	elif cint(self.to_case_no) < cint(self.from_case_no):
		frappe.throw(_("'To Package No.' cannot be less than 'From Package No.'"))
	else:
		ps = frappe.qb.DocType("Packing Slip")
		res = (
			frappe.qb.from_(ps)
			.select(
				ps.name,
			)
			.where(
				(ps.delivery_note == self.delivery_note)
				& (ps.docstatus == 1)
				& (
					(ps.from_case_no.between(self.from_case_no, self.to_case_no))
					| (ps.to_case_no.between(self.from_case_no, self.to_case_no))
					| ((ps.from_case_no <= self.from_case_no) & (ps.to_case_no >= self.from_case_no))
				)
			)
		).run()

		if res:
			frappe.throw(
				_("""Package No(s) already in use. Try from Package No {0}""").format(
					self.get_recommended_case_no()
				)
			)

def validate_items(self):
	references = {}
	for item in self.items:
		if item.qty <= 0:
			frappe.throw(_("Row {0}: Qty must be greater than 0.").format(item.idx))

		if not item.dn_detail and not item.pi_detail:
			frappe.throw(
				_("Row {0}: Either Delivery Note Item or Packed Item reference is mandatory.").format(
					item.idx
				)
			)

		reference = self.get_reference_row(item)
		self.validate_reference_row(item, reference)
		self.validate_remaining_qty(item, flt(reference.qty) - flt(reference.packed_qty))
		references[item.dn_detail or item.pi_detail] = reference

	self.validate_total_qty_per_reference(references)

def validate_total_qty_per_reference(self, references):
	qty_by_reference = {}
	for item in self.items:
		key = item.dn_detail or item.pi_detail
		qty_by_reference[key] = qty_by_reference.get(key, 0) + flt(item.qty)

		reference = references[key]
		remaining_qty = flt(reference.qty) - flt(reference.packed_qty)
		if qty_by_reference[key] > remaining_qty:
			frappe.throw(
				_("Row {0}: Total packed qty cannot be greater than {1} for the Item {2}.").format(
					item.idx, frappe.bold(remaining_qty), frappe.bold(item.item_code)
				)
			)

def get_reference_row(self, item):
	return frappe.db.get_value(
		"Delivery Note Item" if item.dn_detail else "Packed Item",
		{"name": item.dn_detail or item.pi_detail, "docstatus": 0},
		["parent", "item_code", "qty", "packed_qty"],
		as_dict=True,
	)

def validate_reference_row(self, item, reference):
	if not reference or reference.parent != self.delivery_note or reference.item_code != item.item_code:
		frappe.throw(
			_("Row {0}: Please provide a valid Delivery Note Item or Packed Item reference.").format(
				item.idx
			)
		)

def validate_remaining_qty(self, item, remaining_qty):
	if remaining_qty <= 0:
		frappe.throw(
			_("Row {0}: Packing Slip is already created for Item {1}.").format(
				item.idx, frappe.bold(item.item_code)
			)
		)
	elif item.qty > remaining_qty:
		frappe.throw(
			_("Row {0}: Qty cannot be greater than {1} for the Item {2}.").format(
				item.idx, frappe.bold(remaining_qty), frappe.bold(item.item_code)
			)
		)

def set_missing_values(self):
	if not self.from_case_no:
		self.from_case_no = self.get_recommended_case_no()

	for item in self.items:
		weight_per_unit, weight_uom = frappe.db.get_value(
			"Item", item.item_code, ["weight_per_unit", "weight_uom"]
		)

		if weight_per_unit and not item.net_weight:
			item.net_weight = flt(weight_per_unit) * self.get_conversion_factor(item)
		if weight_uom and not item.weight_uom:
			item.weight_uom = weight_uom

def get_conversion_factor(self, item):
	if not item.dn_detail:
		return 1.0

	return flt(frappe.db.get_value("Delivery Note Item", item.dn_detail, "conversion_factor")) or 1.0

def get_recommended_case_no(self):
	"""Returns the next case no. for a new packing slip for a delivery note"""

	return (
		cint(
			frappe.db.get_value(
				"Packing Slip",
				{"delivery_note": self.delivery_note, "docstatus": 1},
				[{"MAX": "to_case_no"}],
			)
		)
		+ 1
	)

def calculate_net_total_pkg(self):
	self.net_weight_uom = self.items[0].weight_uom if self.items else None
	self.gross_weight_uom = self.net_weight_uom

	net_weight_pkg = 0
	for item in self.items:
		if item.weight_uom != self.net_weight_uom:
			frappe.throw(
				_(
					"Different UOM for items will lead to incorrect (Total) Net Weight value. Make sure that Net Weight of each item is in the same UOM."
				)
			)

		net_weight_pkg += flt(item.net_weight) * flt(item.qty)

	self.net_weight_pkg = round(net_weight_pkg, 2)

	if not flt(self.gross_weight_pkg):
		self.gross_weight_pkg = self.net_weight_pkg

def on_discard(self):
	self.update_qc_reference()
	self.db_set("status", "Cancelled")

def validate(self):
	if not self.readings and self.item_code:
		self.get_item_specification_details()

	if self.inspection_type == "In Process" and self.reference_type == "Job Card":
		self.set_acceptance_criteria_from_template()

	if self.readings:
		self.validate_reading_number_format()
		self.inspect_and_set_status()

	self.validate_inspection_required()
	self.validate_status()
	self.set_child_row_reference()
	self.set_company()

def set_acceptance_criteria_from_template(self):
	template = self.quality_inspection_template or frappe.db.get_value(
		"Item", self.item_code, "quality_inspection_template"
	)
	parameters = {d.specification: d for d in get_template_details(template)}
	for reading in self.readings:
		if criteria := parameters.get(reading.specification):
			reading.update(criteria)

def validate_status(self):
	if self.status == "Cancelled" and self.docstatus < 2:
		frappe.throw(_("Status Cancelled can only be set by cancelling the Quality Inspection"))

def set_company(self):
	if self.reference_type and self.reference_name:
		company = frappe.get_cached_value(self.reference_type, self.reference_name, "company")
		if company != self.company:
			self.company = company

def set_child_row_reference(self):
	if self.child_row_reference:
		return

	if not (self.reference_type and self.reference_name):
		return

	doctype = self.reference_type + " Item"
	if self.reference_type == "Stock Entry":
		doctype = "Stock Entry Detail"

	child_doc = frappe.qb.DocType(doctype)
	qi_doc = frappe.qb.DocType("Quality Inspection")

	query = (
		frappe.qb.from_(child_doc)
		.left_join(qi_doc)
		.on(
			(child_doc.name == qi_doc.child_row_reference)
			& (qi_doc.docstatus < 2)
			& (qi_doc.name != self.name)
		)
		.select(child_doc.name)
		.where(
			(child_doc.item_code == self.item_code)
			& (child_doc.parent == self.reference_name)
			& (child_doc.docstatus < 2)
			& (qi_doc.name.isnull())
		)
		.orderby(child_doc.idx)
	)
	if self.batch_no and frappe.get_meta(doctype).has_field("batch_no"):
		query = query.where(child_doc.batch_no == self.batch_no)

	if child_row_references := query.run(pluck=True):
		self.child_row_reference = child_row_references[0]
	elif frappe.get_meta(doctype).has_field("quality_inspection") and self.has_inspected_rows(doctype):
		frappe.throw(
			_("Every row of Item {0} in {1} {2} already has a Quality Inspection").format(
				frappe.bold(self.item_code), _(self.reference_type), frappe.bold(self.reference_name)
			)
		)

def has_inspected_rows(self, doctype):
	return frappe.db.exists(
		doctype,
		{
			"parent": self.reference_name,
			"item_code": self.item_code,
			"quality_inspection": ("not in", ["", self.name]),
		},
	)

def validate_inspection_required(self):
	if frappe.db.get_single_value(
		"Stock Settings", "allow_to_make_quality_inspection_after_purchase_or_delivery"
	):
		return

	if self.reference_type in ["Purchase Receipt", "Purchase Invoice"] and not frappe.get_cached_value(
		"Item", self.item_code, "inspection_required_before_purchase"
	):
		frappe.throw(
			_(
				"'Inspection Required before Purchase' has disabled for the item {0}, no need to create the QI"
			).format(get_link_to_form("Item", self.item_code))
		)

	if self.reference_type in ["Delivery Note", "Sales Invoice"] and not frappe.get_cached_value(
		"Item", self.item_code, "inspection_required_before_delivery"
	):
		frappe.throw(
			_(
				"'Inspection Required before Delivery' has disabled for the item {0}, no need to create the QI"
			).format(get_link_to_form("Item", self.item_code))
		)

def before_submit(self):
	self.validate_sample_size()
	self.validate_readings_status_mandatory()

def validate_sample_size(self):
	if flt(self.sample_size) <= 0:
		frappe.throw(_("Sample Size must be greater than zero"), title=_("Invalid Sample Size"))

def get_item_specification_details(self):
	if not self.quality_inspection_template:
		self.quality_inspection_template = frappe.db.get_value(
			"Item", self.item_code, "quality_inspection_template"
		)

	if not self.quality_inspection_template:
		return

	self.set("readings", [])
	parameters = get_template_details(self.quality_inspection_template)
	for d in parameters:
		child = self.append("readings", {})
		child.update(d)
		child.status = "Accepted"
		child.parameter_group = frappe.get_value(
			"Quality Inspection Parameter", d.specification, "parameter_group"
		)

def get_quality_inspection_template(self):
	template = ""
	if self.bom_no:
		template = frappe.db.get_value("BOM", self.bom_no, "quality_inspection_template")

	if not template:
		template = frappe.db.get_value("BOM", self.item_code, "quality_inspection_template")

	self.quality_inspection_template = template
	self.get_item_specification_details()

def on_update(self):
	action_if_qi_in_draft = frappe.db.get_single_value(
		"Stock Settings", "action_if_quality_inspection_is_not_submitted"
	)

	if not action_if_qi_in_draft or action_if_qi_in_draft == "Warn":
		self.update_qc_reference()

def on_submit(self):
	if (
		frappe.db.get_single_value("Stock Settings", "action_if_quality_inspection_is_not_submitted")
		== "Stop"
	):
		self.update_qc_reference()

def validate_not_used_by_submitted_document(self):
	if not (self.reference_type and self.reference_name) or frappe.db.get_single_value(
		"Stock Settings", "allow_to_make_quality_inspection_after_purchase_or_delivery"
	):
		return

	if frappe.db.get_value(self.reference_type, self.reference_name, "docstatus") != 1:
		return

	if self.is_linked_on_reference():
		frappe.throw(
			_("Quality Inspection {0} is used by {1} {2}. Cancel {2} first.").format(
				frappe.bold(self.name),
				_(self.reference_type),
				get_link_to_form(self.reference_type, self.reference_name),
			)
		)

def is_linked_on_reference(self):
	if self.reference_type == "Job Card":
		return frappe.db.get_value("Job Card", self.reference_name, "quality_inspection") == self.name

	doctype = (
		"Stock Entry Detail" if self.reference_type == "Stock Entry" else self.reference_type + " Item"
	)
	return frappe.db.exists(doctype, {"parent": self.reference_name, "quality_inspection": self.name})

def validate_readings_status_mandatory(self):
	for reading in self.readings:
		if not reading.status:
			frappe.throw(_("Row #{0}: Status is mandatory").format(reading.idx))

def update_qc_reference(self, remove_reference=False):
	quality_inspection = self.name if self.docstatus < 2 and not remove_reference else ""

	if self.reference_type == "Job Card":
		if self.reference_name:
			frappe.db.sql(
				f"""
				UPDATE `tab{self.reference_type}`
				SET quality_inspection = %s, modified = %s
				WHERE name = %s and production_item = %s
			""",
				(quality_inspection, self.modified, self.reference_name, self.item_code),
			)

	else:
		doctype = self.reference_type + " Item"

		if self.reference_type == "Stock Entry":
			doctype = "Stock Entry Detail"

		if doctype and self.reference_name:
			child_doc = frappe.qb.DocType(doctype)

			query = (
				frappe.qb.update(child_doc)
				.set(child_doc.quality_inspection, quality_inspection)
				.where(
					(child_doc.parent == self.reference_name) & (child_doc.item_code == self.item_code)
				)
			)

			if self.batch_no and self.docstatus < 2:
				query = query.where(child_doc.batch_no == self.batch_no)

			if self.docstatus == 2 or remove_reference:
				query = query.where(child_doc.quality_inspection == self.name)
			else:
				query = query.where(IfNull(child_doc.quality_inspection, "").isin(["", self.name]))

			if self.child_row_reference:
				query = query.where(child_doc.name == self.child_row_reference)

			query.run()

			frappe.db.set_value(
				self.reference_type,
				self.reference_name,
				"modified",
				self.modified,
			)

	if self.reference_type and self.reference_name:
		frappe.get_lazy_doc(self.reference_type, self.reference_name).notify_update()

def inspect_and_set_status(self):
	for reading in self.readings:
		if not reading.manual_inspection:  # dont auto set status if manual
			if reading.formula_based_criteria:
				self.set_status_based_on_acceptance_formula(reading)
			else:
				# if not formula based check acceptance values set
				self.set_status_based_on_acceptance_values(reading)

	if not self.manual_inspection:
		self.status = "Accepted"
		for reading in self.readings:
			if reading.status == "Rejected":
				self.status = "Rejected"
				frappe.msgprint(
					_("Status set to rejected as there are one or more rejected readings."), alert=True
				)
				break

def set_status_based_on_acceptance_values(self, reading):
	if not cint(reading.numeric):
		reading_value = reading.get("reading_value") or ""
		value = reading.get("value") or ""
		result = reading_value == value
	else:
		# numeric readings
		result = self.min_max_criteria_passed(reading)

	reading.status = "Accepted" if result else "Rejected"

def min_max_criteria_passed(self, reading):
	"""Determine whether all readings fall in the acceptable range."""
	has_reading = False
	for i in range(1, 11):
		reading_value = reading.get("reading_" + str(i))
		if reading_value is not None and reading_value.strip():
			has_reading = True
			result = (
				flt(reading.get("min_value"))
				<= parse_float(reading_value)
				<= flt(reading.get("max_value"))
			)
			if not result:
				return False
	return has_reading

def set_status_based_on_acceptance_formula(self, reading):
	if not reading.acceptance_formula:
		frappe.throw(
			_("Row #{0}: Acceptance Criteria Formula is required.").format(reading.idx),
			title=_("Missing Formula"),
		)

	condition = reading.acceptance_formula
	data = self.get_formula_evaluation_data(reading)

	try:
		result = frappe.safe_eval(condition, None, data)
		reading.status = "Accepted" if result else "Rejected"
	except NameError as e:
		field = frappe.bold(e.args[0].split()[1])
		frappe.throw(
			_(
				"Row #{0}: {1} is not a valid reading field. Please refer to the field description."
			).format(reading.idx, field),
			title=_("Invalid Formula"),
		)
	except Exception:
		frappe.throw(
			_("Row #{0}: Acceptance Criteria Formula is incorrect.").format(reading.idx),
			title=_("Invalid Formula"),
		)

def get_formula_evaluation_data(self, reading):
	data = {}
	if not cint(reading.numeric):
		data = {"reading_value": reading.get("reading_value")}
	else:
		# numeric readings
		for i in range(1, 11):
			field = "reading_" + str(i)
			if reading.get(field) is None:
				data[field] = 0.0
				continue

			data[field] = parse_float(reading.get(field))
		data["mean"] = self.calculate_mean(reading)

	return data

def calculate_mean(self, reading):
	"""Calculate mean of all non-empty readings."""
	from statistics import mean

	readings_list = []

	for i in range(1, 11):
		reading_value = reading.get("reading_" + str(i))
		if reading_value is not None and reading_value.strip():
			readings_list.append(parse_float(reading_value))

	actual_mean = mean(readings_list) if readings_list else 0
	return actual_mean

def quality_inspection_query(doctype, txt, searchfield, start, page_len, filters):
	return frappe.get_list(
		"Quality Inspection",
		limit_start=start,
		limit_page_length=page_len,
		filters={
			"docstatus": ("<", 2),
			"name": ("like", "%%%s%%" % txt),
			"item_code": filters.get("item_code"),
			"reference_name": ("in", [filters.get("reference_name", ""), ""]),
			"child_row_reference": ("in", [filters.get("child_row_reference", ""), ""]),
		},
		as_list=1,
	)

def make_quality_inspection(source_name, target_doc=None):
	def postprocess(source, doc):
		doc.inspected_by = frappe.session.user
		doc.get_quality_inspection_template()

	doc = get_mapped_doc(
		"BOM",
		source_name,
		{
			"BOM": {
				"doctype": "Quality Inspection",
				"validation": {"docstatus": ["=", 1]},
				"field_map": {"name": "bom_no", "item": "item_code", "stock_uom": "uom", "stock_qty": "qty"},
			}
		},
		target_doc,
		postprocess,
	)

	return doc

def validate_qi_reference(doc, row, item_code=None):
	if not row.get("quality_inspection"):
		return

	qi = frappe.db.get_value(
		"Quality Inspection",
		row.quality_inspection,
		["reference_type", "reference_name", "item_code"],
		as_dict=True,
	)
	if not qi:
		return

	if qi.reference_type != doc.doctype or qi.reference_name != doc.name:
		frappe.throw(
			_(
				"Row #{0}: Please select a valid Quality Inspection with Reference Type {1} and Reference Name {2}."
			).format(row.idx, frappe.bold(doc.doctype), frappe.bold(doc.name))
		)

	if qi.item_code != (item_code or row.item_code):
		frappe.throw(
			_("Row #{0}: Please select a valid Quality Inspection with Item Code {1}.").format(
				row.idx, frappe.bold(item_code or row.item_code)
			)
		)
